import socket, concurrent.futures
# full port scan on 172.31.0.2 and 172.31.0.1 (top 1000-ish + full on .2)
def scan(ip, port):
    try:
        s = socket.create_connection((ip, port), 0.2)
        s.close()
        return (ip, port)
    except Exception:
        return None
jobs=[]
with concurrent.futures.ThreadPoolExecutor(max_workers=200) as ex:
    futs=[ex.submit(scan, '172.31.0.2', p) for p in range(1,12000)]
    for f in concurrent.futures.as_completed(futs):
        r=f.result()
        if r: jobs.append(r)
print('open on .2:', sorted(jobs))
EOF"}

